import { marked } from 'marked';
import { parse } from 'yaml';

export type BookSummary = {
	slug: string;
	title: string;
	author: string;
	year: number;
	rating: number;
	tags: string[];
};

export type Book = BookSummary & { html: string };

const files = import.meta.glob('/content/books/*.md', {
	query: '?raw',
	import: 'default',
	eager: true
}) as Record<string, string>;

function parseBook(path: string, raw: string): Book {
	const slug = path.split('/').pop()!.replace(/\.md$/, '');
	const match = /^---\r?\n([\s\S]*?)\r?\n---\r?\n?([\s\S]*)$/.exec(raw);
	const data = match ? parse(match[1]) : {};
	return {
		slug,
		title: String(data.title),
		author: String(data.author),
		year: Number(data.year),
		rating: Number(data.rating),
		tags: Array.isArray(data.tags) ? data.tags.map(String) : [],
		html: marked.parse(match ? match[2] : raw, { async: false })
	};
}

const books: Book[] = Object.entries(files).map(([path, raw]) => parseBook(path, raw));

const byTitle = (a: { title: string }, b: { title: string }) =>
	a.title < b.title ? -1 : a.title > b.title ? 1 : 0;

function summary({ html: _html, ...rest }: Book): BookSummary {
	return rest;
}

export function listBooks(): BookSummary[] {
	return [...books].sort(byTitle).map(summary);
}

export function topRated(count: number): BookSummary[] {
	return [...books]
		.sort((a, b) => b.rating - a.rating || byTitle(a, b))
		.slice(0, count)
		.map(summary);
}

export function getBook(slug: string): Book | undefined {
	return books.find((b) => b.slug === slug);
}
