<script lang="ts">
	import { enhance } from '$app/forms';
	import { validateContact, type ContactErrors } from '$lib/contact';
	import type { PageProps } from './$types';

	let { form }: PageProps = $props();

	let clientErrors = $state<ContactErrors | null>(null);
	let sent = $state<string | null>(null);

	const errors = $derived<ContactErrors>(clientErrors ?? (form && 'errors' in form ? form.errors : {}));
	const success = $derived(
		sent ?? (form && 'success' in form && form.success ? form.name : null)
	);
