</svelte:head>

<h1>Contact</h1>

{#if success !== null}
	<p role="status">Thanks, {success}! Your message has been sent.</p>
{/if}

<form
	method="POST"
	novalidate
	use:enhance={({ formData, cancel }) => {
		const submitted = {
			name: String(formData.get('name') ?? ''),
			email: String(formData.get('email') ?? ''),
			message: String(formData.get('message') ?? '')
		};
		const found = validateContact(submitted);
		if (Object.keys(found).length > 0) {
			clientErrors = found;
			sent = null;
			cancel();
			return;
		}
